#!/usr/bin/env node
// Concatenate a package's public .d.ts graph into an API report.
// Used where api-extractor cannot follow Node built-ins (Buffer).
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const [entry, pkgName, out] = process.argv.slice(2);
if (!entry || !pkgName || !out) {
  process.stderr.write("usage: dts-api-report.mjs <entry.d.ts> <pkgName> <out.md>\n");
  process.exit(1);
}

const dir = dirname(entry);
const seen = new Set();
const parts = [];

function walk(file) {
  if (seen.has(file)) return;
  seen.add(file);
  const text = readFileSync(file, "utf8").replace(/\/\/# sourceMappingURL=.*\n?/g, "");
  parts.push(text.trimEnd());
  const re = /from ["'](\.[^"']+)["']/g;
  let match;
  while ((match = re.exec(text))) {
    const spec = match[1].replace(/\.js$/, "");
    walk(join(dir, `${spec}.d.ts`));
  }
}

walk(entry);

const body = `## API Report File for "${pkgName}"

> Do not edit this file. It is a report generated from the TypeScript declarations.

\`\`\`ts
${parts.join("\n\n")}
\`\`\`
`;
writeFileSync(out, body);
